-- The ISCAR-DEEP-DRILL code key (Code keys -> Drilling -> ISCAR-DEEP-DRILL), from the ISCAR
-- e-catalog's ISCAR-DEEP-DRILL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.iscardeepdrill', $ck${"title": "ISCAR-DEEP-DRILL code key – deep drills, counterbores, trepanning tools and inserts", "subtitle": "Single and double tube (BTA / ejector) drills with brazed tips or cartridges, counterbores and trepanning tools, and their NPMX / TPMX / XPMT inserts", "example": "DSD-E3 22.91-24.10-DTG", "decoder": "iscar-deep-drill", "sections": [{"key": "t-family", "title": "Tool – system", "sample": "DSD", "rows": [{"code": "DSD", "meaning": "Single tube (BTA) drill"}, {"code": "DDD", "meaning": "Double tube (ejector) drill"}, {"code": "DSC", "meaning": "Single tube counterbore with a through hole"}, {"code": "DDC", "meaning": "Double tube counterboring drill"}, {"code": "DSTR", "meaning": "Single tube trepanning drill"}]}, {"key": "t-connection", "title": "Tool – connection and cutting edge", "sample": "E3", "rows": [{"code": "E0", "meaning": "External single thread connection, single brazed tip"}, {"code": "E1", "meaning": "External 2 and 4 start thread connection, single brazed tip"}, {"code": "E2", "meaning": "External 2 and 4 start thread connection, 2 brazed tips"}, {"code": "E3", "meaning": "External 4 start thread connection, 3 brazed tips"}, {"code": "EC", "meaning": "External 4-start thread connection, cartridges"}, {"code": "IC", "meaning": "Internal single-start thread connection, cartridges"}, {"code": "EA", "meaning": "External 4-start thread, adjustable diameter"}, {"code": "IA", "meaning": "Internal single-start thread, adjustable diameter"}]}, {"key": "t-dia", "title": "Tool – diameter range", "rows": [{"code": "##.##-##.##", "meaning": "Diameter range in mm"}]}, {"key": "t-line", "title": "Tool – version", "rows": [{"code": "NOM #", "meaning": "Nominal version (see the catalog) (inferred)"}, {"code": "DTH", "meaning": "Brazed tip geometry H (see the catalog)"}, {"code": "DTL", "meaning": "Brazed tip geometry L (see the catalog)"}, {"code": "DTG", "meaning": "Brazed tip geometry G (see the catalog)"}]}, {"key": "i-family", "title": "Insert – family", "sample": "TPMX", "rows": [{"code": "NPMX", "meaning": "Inserts with 2 cutting edges for DSD-EC / DDD-EC / DSD-IC heads"}, {"code": "TPMX", "meaning": "Inserts with 3 cutting edges for drilling, counterboring and trepanning tools"}, {"code": "XPMT", "meaning": "Inserts for DSD / DSC drilling and boring heads"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "##", "meaning": "Insert size"}, {"code": "#####", "meaning": "XPMT size code"}]}, {"key": "i-thick", "title": "Insert – thickness", "rows": [{"code": "##", "meaning": "Insert thickness code"}]}, {"key": "i-radius", "title": "Insert – corner radius", "rows": [{"code": "##", "meaning": "Corner radius x10"}]}, {"key": "i-hand", "title": "Insert – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "B", "meaning": "B chipformer (inferred)"}, {"code": "G", "meaning": "G chipformer (inferred)"}, {"code": "BG", "meaning": "BG chipformer (inferred)"}, {"code": "DT", "meaning": "General use"}, {"code": "UB", "meaning": "XPMT for DSD / DSC heads"}, {"code": "45", "meaning": "XPMT for DSC boring heads (45°)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
